package jp.terada.midnitelogger;
import android.content.*; import android.net.*; import android.net.wifi.*; import java.util.*;
public class WifiController { final Context c; final WifiManager w; WifiController(Context c){this.c=c;w=(WifiManager)c.getSystemService(Context.WIFI_SERVICE);} int idFor(String ssid){for(WifiConfiguration x:w.getConfiguredNetworks())if(x.SSID!=null&&x.SSID.replace("\"","").equals(ssid))return x.networkId;return -1;} boolean connect(String ssid,int timeoutSec)throws InterruptedException{int id=idFor(ssid);if(id<0)return false;w.disconnect();w.enableNetwork(id,true);w.reconnect();long end=System.currentTimeMillis()+timeoutSec*1000L;while(System.currentTimeMillis()<end){WifiInfo x=w.getConnectionInfo();if(x!=null&&x.getSSID()!=null&&x.getSSID().replace("\"","").equals(ssid)&&x.getIpAddress()!=0)return true;Thread.sleep(1000);}return false;} String bestCandidate(String logger){w.startScan();try{Thread.sleep(5000);}catch(Exception e){}Set<String> configured=new HashSet<String>();for(WifiConfiguration x:w.getConfiguredNetworks())if(x.SSID!=null)configured.add(x.SSID.replace("\"",""));ScanResult best=null;for(ScanResult r:w.getScanResults())if(configured.contains(r.SSID)&&!r.SSID.equals(logger)&&r.level>=-75&&(best==null||r.level>best.level))best=r;return best==null?null:best.SSID;} }
